  LOOP
    -- Cliente (so cria se nao existir com esse CNPJ)
    SELECT id INTO v_cliente_id FROM public.clientes
      WHERE regexp_replace(cnpj, '[^0-9]', '', 'g') = r.cnpj_digits;

    IF v_cliente_id IS NULL THEN
      INSERT INTO public.clientes
        (owner_id, razao_social, nome_fantasia, cnpj, endereco, bairro, cidade, estado, cep,
         peso_franquia, valor_franquia, valor_kg_excedente, status)
      VALUES
        (v_owner_id, r.razao_social, r.razao_social, r.cnpj, r.endereco, r.bairro, r.cidade, r.estado, r.cep,
         20, 150.00, 3.50, 'ativo')
      RETURNING id INTO v_cliente_id;
    END IF;

    -- Contrato (so cria se esse numero ainda nao existir para esse cliente)
    SELECT id INTO v_contrato_id FROM public.contratos
      WHERE numero = r.numero_contrato AND cliente_id = v_cliente_id;

    IF v_contrato_id IS NULL THEN
      INSERT INTO public.contratos
        (owner_id, cliente_id, numero, status, data_inicio, data_fim, valor_mensal, grupos_residuos,
         limite_kg, valor_excedente, forma_pagamento, observacoes)
